CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_student_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, full_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name','')); RETURN NEW; END $$;
CREATE TRIGGER create_student_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_student_profile();
CREATE TABLE public.students (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, dni text NOT NULL UNIQUE CHECK (dni ~ '^[0-9]{8}[A-Z]$'), email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.students TO authenticated; GRANT ALL ON public.students TO service_role;
ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;
CREATE POLICY students_own_read ON public.students FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL CHECK(role IN ('admin','student')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own_read ON public.user_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL CHECK(category IN ('practice','pack','fee')), price_cents integer CHECK(price_cents > 0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_students_read ON public.products FOR SELECT TO authenticated USING(active AND EXISTS(SELECT 1 FROM public.students WHERE user_id = auth.uid()));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES public.students(user_id), total_cents integer NOT NULL CHECK(total_cents > 0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','cancelled','refunded')), provider text NOT NULL CHECK(provider IN ('stripe','redsys')), provider_reference text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_own_read ON public.orders FOR SELECT TO authenticated USING(student_id = auth.uid());
CREATE TABLE public.order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id), product_name text NOT NULL, quantity integer NOT NULL CHECK(quantity > 0 AND quantity <= 20), unit_price_cents integer NOT NULL CHECK(unit_price_cents > 0));
GRANT SELECT ON public.order_items TO authenticated; GRANT ALL ON public.order_items TO service_role;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_items_own_read ON public.order_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders WHERE orders.id = order_id AND student_id = auth.uid()));
CREATE TABLE public.dni_login_limits (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.dni_login_limits TO service_role;
ALTER TABLE public.dni_login_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_dni_login_attempt(attempt_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.dni_login_limits(key,attempts) VALUES(attempt_key,1) ON CONFLICT(key) DO UPDATE SET attempts=CASE WHEN dni_login_limits.window_start < now()-interval '15 minutes' THEN 1 ELSE dni_login_limits.attempts+1 END, window_start=CASE WHEN dni_login_limits.window_start < now()-interval '15 minutes' THEN now() ELSE dni_login_limits.window_start END RETURNING attempts INTO n; RETURN n<=10; END $$;
REVOKE ALL ON FUNCTION public.consume_dni_login_attempt(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_dni_login_attempt(text) TO service_role;